def check_character_count(S: str) -> str:
    cnt = {}
    for s in S:
        if s in cnt:
            cnt[s] += 1
        else:
            cnt[s] = 1

    freq_count = {}
    for frequency in cnt.values():
        if frequency in freq_count:
            freq_count[frequency] += 1
        else:
            freq_count[frequency] = 1

    ans = "Yes"
    for count in freq_count.values():
        if count != 2:
            ans = "No"
            break
    return ans
